INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1853942, 255488, 45857, '<td valign="top">This is an uncomfortable image. IMO the tonal values are skewed, It would work better if the sky were darker and the central land areas were lighter/brighter showing more detail. Perhaps it something that could be done with shadow and midtone adjustments via curves</td>', 'This is an uncomfortable image. IMO the tonal values are skewed, It would work better if the sky were darker and the central land areas were lighter/brighter showing more detail. Perhaps it something that could be done with shadow and midtone adjustments via curves', '2005-11-10 05:05:08.000000', NULL, 1),
(1853944, 254622, 45857, '<td valign="top">Neat idea, and neat place.</td>', 'Neat idea, and neat place.', '2005-11-10 05:07:52.000000', NULL, 1),
(1853951, 254922, 45857, '<td valign="top">Deja vu all over again.... beautiful shot of one of my favorite cities<br/>(I would love to see the GPS data  on the cameras for the two shots in the challenge, got to be within feet.)  8</td>', 'Deja vu all over again.... beautiful shot of one of my favorite cities(I would love to see the GPS data  on the cameras for the two shots in the challenge, got to be within feet.)  8', '2005-11-10 05:20:31.000000', NULL, 1),
