(1858241, 254112, 36397, '<td valign="top">Gee! What is this? A bridge? Nice picture, almost art but doesn''t really fit in the challenge. Technically the scene is a bit hazy.</td>', 'Gee! What is this? A bridge? Nice picture, almost art but doesn''t really fit in the challenge. Technically the scene is a bit hazy.', '2005-11-11 13:46:14.000000', NULL, 1),
(1858248, 255041, 40019, '<td valign="top">Very cool shot!  Good use of wide angle! Great color saturation - nicely done.</td>', 'Very cool shot!  Good use of wide angle! Great color saturation - nicely done.', '2005-11-11 13:50:22.000000', NULL, 1),
(1858251, 254369, 40019, '<td valign="top">Nice exposure, good color saturation.</td>', 'Nice exposure, good color saturation.', '2005-11-11 13:50:55.000000', NULL, 1),
