(1860228, 255486, 10515, '<td valign="top">I always love moving water... so silky.. the foreground twigs are kind of distracting.</td>', 'I always love moving water... so silky.. the foreground twigs are kind of distracting.', '2005-11-12 10:50:43.000000', NULL, 1),
(1860229, 255186, 45672, '<td valign="top">Nice shot.  As much as I hate to see graffiti, this is really cool.  Nice going.</td>', 'Nice shot.  As much as I hate to see graffiti, this is really cool.  Nice going.', '2005-11-12 10:50:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1860230, 255295, 45672, '<td valign="top">Cool shot.  I just visited Baltimore last summer for the first time.  This looks familiar.  The shot appears to be a little fuzzy.  You probably took it free-hand, but I like the shot and all the lights, etc.</td>', 'Cool shot.  I just visited Baltimore last summer for the first time.  This looks familiar.  The shot appears to be a little fuzzy.  You probably took it free-hand, but I like the shot and all the lights, etc.', '2005-11-12 10:52:14.000000', NULL, 1),
(1860233, 255253, 30605, '<td valign="top">2/3 of the photo is a big black void. Still a nice picture, but would have been better with the horizon at the bottom 1/3</td>', '2/3 of the photo is a big black void. Still a nice picture, but would have been better with the horizon at the bottom 1/3', '2005-11-12 10:53:49.000000', NULL, 1),
(1860234, 255450, 45672, '<td valign="top">Well, this is pretty amazing.  What a great location to be doing photography.  I think I would have liked it better if the branch wasn''t running right through the middle of the picture.  I notice your natural framing job, but I think it is a little distracting in this case.  Good attempt.</td>', 'Well, this is pretty amazing.  What a great location to be doing photography.  I think I would have liked it better if the branch wasn''t running right through the middle of the picture.  I notice your natural framing job, but I think it is a little distracting in this case.  Good attempt.', '2005-11-12 10:54:30.000000', NULL, 1),
(1860235, 254916, 45672, '<td valign="top">I''m a real sucker for the Golden Gate.  Well done!  10</td>', 'I''m a real sucker for the Golden Gate.  Well done!  10', '2005-11-12 10:55:29.000000', NULL, 1),
(1860238, 253264, 30605, '<td valign="top">I can actually see the pixel block. Not good.</td>', 'I can actually see the pixel block. Not good.', '2005-11-12 10:56:14.000000', NULL, 1),
(1860240, 255541, 45672, '<td valign="top">Yes, I''ll take one of those fancy pineapple drinks please.  Oh, don''t forget the little umbrella.  Nice shot.  I always like a good beach landscape.</td>', 'Yes, I''ll take one of those fancy pineapple drinks please.  Oh, don''t forget the little umbrella.  Nice shot.  I always like a good beach landscape.', '2005-11-12 10:59:10.000000', NULL, 1),
(1860242, 254810, 45672, '<td valign="top">Nice shot.  I like the yucca plant.  That is a nice addition to the picture.</td>', 'Nice shot.  I like the yucca plant.  That is a nice addition to the picture.', '2005-11-12 11:00:16.000000', NULL, 1),
(1860245, 253495, 45672, '<td valign="top">Great shot and good use of the shutter speed.  It would be perfect if it wasn''t for that little stick sticking out of the water in the very bottom dead center of the picture.  It is a little distracting, but way to go on the shot.  This is just awesome.</td>', 'Great shot and good use of the shutter speed.  It would be perfect if it wasn''t for that little stick sticking out of the water in the very bottom dead center of the picture.  It is a little distracting, but way to go on the shot.  This is just awesome.', '2005-11-12 11:02:13.000000', NULL, 1),
(1860247, 255275, 30605, '<td valign="top">Very nice composition. Photo nicely divided in blue (sort of), yellow and green</td>', 'Very nice composition. Photo nicely divided in blue (sort of), yellow and green', '2005-11-12 11:03:41.000000', NULL, 1),
(1860248, 255156, 30605, '<td valign="top">This got to be the winner here. I have nothing to say except you acheive perfection. You got an exceptional point of view here. 10</td>', 'This got to be the winner here. I have nothing to say except you acheive perfection. You got an exceptional point of view here. 10', '2005-11-12 11:03:48.000000', NULL, 1),
