INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1862596, 253570, 24546, '<td valign="top">This shot would have been stronger if you had cropped to a 4X5 aspect ration rather than 4X6. That would put your major horizontal line in the photo at the lower horizontal thirds line and put your moon on the upper thirds line.  5</td>', 'This shot would have been stronger if you had cropped to a 4X5 aspect ration rather than 4X6. That would put your major horizontal line in the photo at the lower horizontal thirds line and put your moon on the upper thirds line.  5', '2005-11-13 17:52:49.000000', NULL, 1),
(1862597, 255367, 44829, '<td valign="top">Beautiful. Maybee a little less sky and more grass?</td>', 'Beautiful. Maybee a little less sky and more grass?', '2005-11-13 17:52:54.000000', NULL, 1),
(1862598, 255180, 44829, '<td valign="top">Great title. Wonderful colours and viewpoint.</td>', 'Great title. Wonderful colours and viewpoint.', '2005-11-13 17:53:38.000000', NULL, 1),
