(1862956, 254922, 47151, '<td valign="top">I love the color. makes me want to find this place and sit in awe for hours on end.</td>', 'I love the color. makes me want to find this place and sit in awe for hours on end.', '2005-11-13 20:01:00.000000', NULL, 1),
(1862957, 255607, 24546, '<td valign="top">I would have liked this one a lot better if you had captured the rainbow over something more scenic than a parking lot for this challenge. The foreground feels very dark.</td>', 'I would have liked this one a lot better if you had captured the rainbow over something more scenic than a parking lot for this challenge. The foreground feels very dark.', '2005-11-13 20:01:04.000000', NULL, 1),
(1862961, 254848, 40155, '<td valign="top">Beautiful colours, nice composition...just a little too micro for a challenge that implies a view from far away.</td>', 'Beautiful colours, nice composition...just a little too micro for a challenge that implies a view from far away.', '2005-11-13 20:02:14.000000', NULL, 1),
